const text = (n,nullable=false) => `${n} TEXT ${nullable?"":"NOT NULL "}CHECK (${nullable?`${n} IS NULL OR `:""}(typeof(${n})='text' AND length(${n}) BETWEEN 1 AND 256 AND instr(${n},char(0))=0))`;
const time = (n,nullable=false) => `${n} TEXT ${nullable?"":"NOT NULL "}CHECK (${nullable?`${n} IS NULL OR `:""}(typeof(${n})='text' AND length(${n}) BETWEEN 1 AND 200 AND instr(${n},char(0))=0 AND julianday(${n}) IS NOT NULL))`;
const hash=(n,nullable=false)=>`${n} TEXT ${nullable?"":"NOT NULL "}CHECK (${nullable?`${n} IS NULL OR `:""}(typeof(${n})='text' AND length(${n})=64 AND ${n} NOT GLOB '*[^0-9a-f]*' AND instr(${n},char(0))=0))`;
const size=(n,nullable=false)=>`${n} INTEGER ${nullable?"":"NOT NULL "}CHECK (${nullable?`${n} IS NULL OR `:""}(typeof(${n})='integer' AND ${n} BETWEEN 0 AND 104857600))`;
