add(`-- Precondition before any DDL: NULL legacy primary keys cannot name a durable slot.
SELECT CASE WHEN ${sourceTables.map((table)=>`EXISTS(SELECT 1 FROM ${table} WHERE ${[...new Set(slots.filter((s)=>s.table===table).flatMap((s)=>[s.id??"id",s.sub].filter(Boolean)))].map((k)=>`${k} IS NULL`).join(" OR ")})`).join(" OR ")} THEN json('Shadow transition requires addressable non-NULL legacy consumer keys') ELSE 1 END;`);
add(`-- Generated by scripts/generate-file-shadow-migration.mjs. Review SQL and generator together.
-- V15 installs an inert runtime gate and legacy-mode sidecar capture. No provider I/O.
-- Typed business columns and V14 decisions remain empty until a separate activation.
CREATE TABLE file_shadow_dependency_versions(dependency_kind TEXT NOT NULL,dependency_key TEXT NOT NULL CHECK(json_valid(dependency_key)),revision INTEGER NOT NULL CHECK(typeof(revision)='integer' AND revision>0),present INTEGER NOT NULL CHECK(present IN(0,1)),snapshot_json TEXT NOT NULL CHECK(json_valid(snapshot_json)),PRIMARY KEY(dependency_kind,dependency_key,revision)) WITHOUT ROWID;
CREATE TABLE file_shadow_control(singleton INTEGER PRIMARY KEY NOT NULL CHECK(singleton=1),epoch INTEGER NOT NULL CHECK(typeof(epoch)='integer' AND epoch>=0)) WITHOUT ROWID;
INSERT INTO file_shadow_control VALUES(1,0);
CREATE TABLE file_shadow_runtime_guard(singleton INTEGER PRIMARY KEY NOT NULL CHECK(singleton=1),${text("incarnation",true)},enabled INTEGER NOT NULL CHECK(enabled IN(0,1)),${text("enabled_by",true)},${time("updated_at")},CHECK(enabled=0 OR (incarnation IS NOT NULL AND enabled_by IS NOT NULL))) WITHOUT ROWID;
INSERT INTO file_shadow_runtime_guard VALUES(1,NULL,0,NULL,'2026-09-25T00:00:00.000Z');
CREATE TABLE file_shadow_runtime_incarnations(${text("incarnation")} PRIMARY KEY,${text("enabled_by")},${time("enabled_at")}) WITHOUT ROWID;
CREATE TABLE file_shadow_enablements(singleton INTEGER PRIMARY KEY NOT NULL CHECK(singleton=1),expected_epoch INTEGER NOT NULL CHECK(typeof(expected_epoch)='integer' AND expected_epoch>=0),${text("enabled_by")},${time("enabled_at")}) WITHOUT ROWID;
CREATE TABLE file_shadow_occurrences(${text("id")} PRIMARY KEY,${keyColumns},generation INTEGER NOT NULL CHECK(typeof(generation)='integer' AND generation>0),present INTEGER NOT NULL CHECK(present IN(0,1)),source_rowid INTEGER,source_json TEXT NOT NULL CHECK(json_valid(source_json) AND json_type(source_json)='object'),legacy_store_kind TEXT CHECK(legacy_store_kind IS NULL OR legacy_store_kind IN('r2','managed')),legacy_provider TEXT,legacy_object_key TEXT,${purposeCheck("expected_purpose",true)},observed_epoch INTEGER NOT NULL CHECK(typeof(observed_epoch)='integer' AND observed_epoch>=0),${time("observed_at")},UNIQUE(${keys.join(",")},generation),${slotCheck},CHECK((present=1 AND source_rowid IS NOT NULL) OR (present=0 AND source_rowid IS NULL AND legacy_store_kind IS NULL AND legacy_provider IS NULL AND legacy_object_key IS NULL)),CHECK((legacy_store_kind IS NULL AND legacy_provider IS NULL AND legacy_object_key IS NULL) OR (legacy_store_kind='r2' AND legacy_provider='r2' AND legacy_object_key IS NOT NULL) OR (legacy_store_kind='managed' AND legacy_provider IS NOT NULL AND legacy_object_key IS NOT NULL))) WITHOUT ROWID;
CREATE TABLE file_shadow_heads(${keyColumns},generation INTEGER NOT NULL,occurrence_id TEXT NOT NULL UNIQUE REFERENCES file_shadow_occurrences(id) ON DELETE RESTRICT,present INTEGER NOT NULL CHECK(present IN(0,1)),source_rowid INTEGER,source_json TEXT NOT NULL CHECK(json_valid(source_json)),observed_epoch INTEGER NOT NULL,PRIMARY KEY(${keys.join(",")}),${slotCheck}) WITHOUT ROWID;
CREATE TABLE file_shadow_closures(occurrence_id TEXT PRIMARY KEY NOT NULL REFERENCES file_shadow_occurrences(id) ON DELETE RESTRICT,successor_occurrence_id TEXT NOT NULL UNIQUE REFERENCES file_shadow_occurrences(id) ON DELETE RESTRICT,closed_epoch INTEGER NOT NULL,${time("closed_at")},CHECK(occurrence_id<>successor_occurrence_id)) WITHOUT ROWID;`);
add(`CREATE TABLE file_shadow_operations(${text("id")} PRIMARY KEY,occurrence_id TEXT NOT NULL REFERENCES file_shadow_occurrences(id) ON DELETE RESTRICT,captured_epoch INTEGER NOT NULL CHECK(typeof(captured_epoch)='integer' AND captured_epoch>=0),${hash("baseline_sha256")},${purposeCheck("purpose",true)},access_scope TEXT NOT NULL CHECK(access_scope='system'),source_store_kind TEXT CHECK(source_store_kind IS NULL OR source_store_kind IN('r2','managed')),source_provider TEXT,source_object_key TEXT,source_profile_id TEXT REFERENCES storage_profiles(id) ON DELETE RESTRICT,source_profile_revision INTEGER CHECK(source_profile_revision IS NULL OR source_profile_revision=1),${size("source_expected_byte_size",true)},${hash("source_expected_sha256",true)},destination_profile_id TEXT REFERENCES storage_profiles(id) ON DELETE RESTRICT,destination_profile_revision INTEGER CHECK(destination_profile_revision IS NULL OR destination_profile_revision=1),status TEXT NOT NULL CHECK(status IN('pending','resolved','admitted_unresolved','cancelled')),${text("created_by")},${time("created_at")},${time("completed_at",true)},CHECK((status='pending' AND completed_at IS NULL) OR (status<>'pending' AND completed_at IS NOT NULL AND julianday(completed_at)>=julianday(created_at)))) WITHOUT ROWID;
CREATE TABLE file_shadow_attempts(${text("id")} PRIMARY KEY,operation_id TEXT NOT NULL REFERENCES file_shadow_operations(id) ON DELETE RESTRICT,attempt_number INTEGER NOT NULL CHECK(typeof(attempt_number)='integer' AND attempt_number>0),${text("owner_token")},${text("runtime_incarnation")},candidate_file_id TEXT UNIQUE REFERENCES files(id) ON DELETE RESTRICT,candidate_location_id TEXT UNIQUE REFERENCES file_locations(id) ON DELETE RESTRICT,candidate_object_key TEXT CHECK(candidate_object_key IS NULL OR (length(candidate_object_key) BETWEEN 1 AND 4096 AND instr(candidate_object_key,char(0))=0)),${size("verified_byte_size",true)},${hash("verified_sha256",true)},${time("source_verified_at",true)},state TEXT NOT NULL CHECK(state IN('staged','write_started','unknown','verified','published','failed','cancelled')),${time("lease_expires_at")},${time("created_at")},${time("write_started_at",true)},${time("verified_at",true)},${time("completed_at",true)},last_error TEXT CHECK(last_error IS NULL OR (length(last_error) BETWEEN 1 AND 1000 AND instr(last_error,char(0))=0)),UNIQUE(operation_id,attempt_number),CHECK(julianday(lease_expires_at)>julianday(created_at)),CHECK((candidate_file_id IS NULL AND candidate_location_id IS NULL AND candidate_object_key IS NULL AND verified_byte_size IS NULL AND verified_sha256 IS NULL AND source_verified_at IS NULL) OR (candidate_file_id IS NOT NULL AND candidate_location_id IS NOT NULL AND candidate_object_key IS NOT NULL AND verified_byte_size IS NOT NULL AND verified_sha256 IS NOT NULL AND source_verified_at IS NOT NULL)),CHECK(state NOT IN('write_started','unknown','verified','published') OR candidate_file_id IS NOT NULL),CHECK(state NOT IN('write_started','unknown','verified','published') OR write_started_at IS NOT NULL),CHECK(state NOT IN('verified','published') OR verified_at IS NOT NULL),CHECK(state NOT IN('published','failed','cancelled') OR completed_at IS NOT NULL)) WITHOUT ROWID;
CREATE TABLE file_shadow_decisions(occurrence_id TEXT PRIMARY KEY NOT NULL REFERENCES file_shadow_occurrences(id) ON DELETE RESTRICT,operation_id TEXT NOT NULL UNIQUE REFERENCES file_shadow_operations(id) ON DELETE RESTRICT,decision TEXT NOT NULL CHECK(decision IN('resolved','admitted_unresolved')),file_id TEXT REFERENCES files(id) ON DELETE RESTRICT,location_id TEXT REFERENCES file_locations(id) ON DELETE RESTRICT,${hash("baseline_sha256")},reason TEXT CHECK(reason IS NULL OR (length(reason) BETWEEN 1 AND 1000 AND instr(reason,char(0))=0)),${text("decided_by")},${time("decided_at")},CHECK((decision='resolved' AND file_id IS NOT NULL AND location_id IS NOT NULL AND reason IS NULL) OR (decision='admitted_unresolved' AND file_id IS NULL AND location_id IS NULL AND reason IS NOT NULL))) WITHOUT ROWID;
CREATE TABLE file_shadow_legacy_holds(${text("id")} PRIMARY KEY,operation_id TEXT NOT NULL REFERENCES file_shadow_operations(id) ON DELETE RESTRICT,store_kind TEXT NOT NULL CHECK(store_kind IN('r2','managed')),provider TEXT NOT NULL,object_key TEXT NOT NULL,storage_profile_id TEXT NOT NULL REFERENCES storage_profiles(id) ON DELETE RESTRICT,profile_revision INTEGER NOT NULL CHECK(profile_revision=1),${time("acquired_at")},${time("released_at",true)},UNIQUE(operation_id,store_kind,provider,object_key,storage_profile_id),CHECK(released_at IS NULL OR julianday(released_at)>=julianday(acquired_at))) WITHOUT ROWID;
CREATE TABLE file_shadow_legacy_deletion_claims(store_kind TEXT NOT NULL CHECK(store_kind IN('r2','managed')),provider TEXT NOT NULL,object_key TEXT NOT NULL,first_state TEXT NOT NULL CHECK(first_state IN('deleting','deleted')),operation_id TEXT,observed_at TEXT NOT NULL,PRIMARY KEY(store_kind,provider,object_key)) WITHOUT ROWID;
INSERT INTO file_shadow_legacy_deletion_claims SELECT store_kind,provider,object_key,state,operation_id,updated_at FROM blob_gc_ledger WHERE state IN('deleting','deleted');
CREATE INDEX file_shadow_occurrences_epoch_idx ON file_shadow_occurrences(observed_epoch,id);
CREATE INDEX file_shadow_operations_occurrence_idx ON file_shadow_operations(occurrence_id,status);
CREATE UNIQUE INDEX file_shadow_operations_pending_occurrence_idx ON file_shadow_operations(occurrence_id) WHERE status='pending';
CREATE INDEX file_shadow_attempts_operation_idx ON file_shadow_attempts(operation_id,state);
CREATE INDEX file_shadow_legacy_holds_locator_idx ON file_shadow_legacy_holds(store_kind,provider,object_key,released_at);`);
add(`CREATE TABLE file_shadow_profile_enablements(storage_profile_id TEXT PRIMARY KEY NOT NULL REFERENCES storage_profiles(id) ON DELETE RESTRICT,configuration_revision INTEGER NOT NULL CHECK(configuration_revision=1),${text("enabled_by")},${time("enabled_at")}) WITHOUT ROWID;
CREATE TABLE file_shadow_reconciliations(${text("id")} PRIMARY KEY,attempt_id TEXT NOT NULL REFERENCES file_shadow_attempts(id) ON DELETE RESTRICT,${text("runtime_incarnation")},verified_epoch INTEGER NOT NULL CHECK(typeof(verified_epoch)='integer' AND verified_epoch>=0),${size("verified_byte_size")},${hash("verified_sha256")},${time("source_verified_at")},${time("destination_verified_at")},${text("created_by")},${time("created_at")},UNIQUE(attempt_id,runtime_incarnation,verified_epoch),CHECK(julianday(created_at)>=julianday(source_verified_at) AND julianday(created_at)>=julianday(destination_verified_at))) WITHOUT ROWID;
CREATE TABLE file_shadow_checkpoints(${text("id")} PRIMARY KEY,captured_epoch INTEGER NOT NULL,current_count INTEGER NOT NULL CHECK(current_count>=0),resolved_count INTEGER NOT NULL CHECK(resolved_count>=0),unresolved_count INTEGER NOT NULL CHECK(unresolved_count>=0),pending_count INTEGER NOT NULL CHECK(pending_count>=0),${text("captured_by")},${time("captured_at")},CHECK(current_count=resolved_count+unresolved_count+pending_count)) WITHOUT ROWID;`);
// Dependency payloads are recorded once. Expanding their full JSON inside every
// nested source/owner trigger exceeds D1's VDBE preparation budget.
const dependencySpecs=new Map();
const dependencyKeyColumns={state_representations:["hash"],storage_profile_runtime:["storage_profile_id"],comment_submission_targets:["submission_id","run_step_id"],comment_item_acceptances:["item_id"],comment_submission_acceptances:["submission_id"],legacy_file_mappings:["store_kind","provider","object_key"],blob_gc_ledger:["store_kind","provider","object_key"],blob_integrity_quarantine:["store_kind","provider","object_key"]};
const dependencyKey=(table,alias)=>`json_array(${(dependencyKeyColumns[table]??["id"]).map((k)=>jsonScalar(alias?`${alias}.${k}`:k)).join(",")})`;
function registerDependency(table,columns){ const values=dependencySpecs.get(table)??new Set(); for(const column of columns.split(" "))values.add(column); dependencySpecs.set(table,values); }
const dependencyToken=(table,alias)=>`json_object('dependency_key',${dependencyKey(table,alias)},'revision',(SELECT MAX(v.revision) FROM file_shadow_dependency_versions v WHERE v.dependency_kind=${q(table)} AND v.dependency_key=${dependencyKey(table,alias)}))`;
const jsonRow=(table,alias,columns,where)=>{registerDependency(table,columns);return `(SELECT ${dependencyToken(table,alias)} FROM ${table} ${alias} WHERE ${where})`;};
const jsonRows=(table,alias,columns,where,order="id")=>{registerDependency(table,columns);return `(SELECT json_group_array(json(value)) FROM(SELECT ${dependencyToken(table,alias)} value FROM ${table} ${alias} WHERE ${where} ORDER BY ${order.split(" ").map((k)=>`${alias}.${k}`).join(",")}))`;};
function dependencyJson(s,rk,mk,mp) {
  const key=`COALESCE((${rk}),(${mk}))`;
  const sampleCols="id status deleted_at updated_at",runCols="id sample_id status deleted_at completed_at last_mutation_id",stepCols="id run_id status plan_status deleted_at updated_at last_mutation_id";
  const sub=s.table==="comment_submission_items"||s.table==="run_step_comments"?"x.submission_id":"NULL";
  const step=s.table==="run_step_assets"||s.table==="run_step_comments"?"x.run_step_id":s.table==="state_verifications"?"x.after_run_step_id":"NULL";
  const sample=s.table==="events"||s.table==="state_verifications"?"x.sample_id":`COALESCE((SELECT sample_id FROM runs WHERE id=(SELECT run_id FROM run_steps WHERE id=${step})),(SELECT sample_id FROM comment_submissions WHERE id=${sub}))`;
  const parts={
    sourceAsset:s.asset?jsonRow("assets","ar","id import_id r2_key status sha256 byte_size created_at",`ar.id=x.${s.asset}`):jsonRow("assets","ar","id import_id r2_key status sha256 byte_size created_at",`ar.r2_key=(${rk})`),
    sourceManaged:s.managed?jsonRow("managed_storage_objects","mr","id provider object_key status sha256 byte_size orphaned_at created_at",`mr.id=x.${s.managed}`):"NULL",
    ownerImport:jsonRow("imports","io","id status operation_id lease_expires_at recovery_operation_id completed_at storage_profile_id storage_profile_revision request_sha256 request_scope accepted_result_json",`io.id=(SELECT import_id FROM assets WHERE r2_key=(${rk}))`),
    sample:jsonRow("samples","ss",sampleCols,`ss.id=${sample}`),
    run:jsonRow("runs","rr",runCols,`rr.id=(SELECT run_id FROM run_steps WHERE id=${step})`),
    step:jsonRow("run_steps","rs",stepCols,`rs.id=${step}`),
    submission:jsonRow("comment_submissions","cs","id context_kind sample_id scope status updated_at completed_at cancelled_at deleted_at deletion_operation_id retry_until retry_closed_at last_mutation_id",`cs.id=${sub}`),
    submissionTargets:jsonRows("comment_submission_targets","ct","submission_id sample_id run_id run_step_id expected_updated_at",`ct.submission_id=${sub}`,"submission_id run_step_id"),
    targetSteps:jsonRows("run_steps","ts",stepCols,`ts.id IN(SELECT run_step_id FROM comment_submission_targets WHERE submission_id=${sub})`),
    targetRuns:jsonRows("runs","tr",runCols,`tr.id IN(SELECT run_id FROM comment_submission_targets WHERE submission_id=${sub})`),
    targetSamples:jsonRows("samples","ts",sampleCols,`ts.id IN(SELECT sample_id FROM comment_submission_targets WHERE submission_id=${sub})`),
    pairedItem:s.table==="comment_submission_items"?jsonRow("comment_submission_items","ci","id submission_id kind status asset_id storage_object_id sha256 byte_size related_item_id updated_at deleted_at","ci.id=x.related_item_id"):"NULL",
    state:s.table==="state_representation_assets"?jsonRow("state_representations","sr","hash hash_scheme representation_type logical_state_key created_at","sr.hash=x.state_hash"):"NULL",
    template:s.table==="metrology_template_references"?jsonRow("template_versions","tv","id template_kind source_asset_key archived_at deleted_at locked_at","tv.id=x.template_version_id"):"NULL",
    projectContent:s.table==="project_content_attachments"?jsonRow("project_contents","pc","id project_id content_type revision last_mutation_id updated_at deleted_at deletion_operation_id","pc.id=x.project_content_id"):"NULL",
    project:s.table==="project_content_attachments"?jsonRow("projects","pr","id revision last_mutation_id updated_at deleted_at deletion_operation_id","pr.id=(SELECT project_id FROM project_contents WHERE id=x.project_content_id)"):"NULL",
    projectItem:s.table==="project_content_attachments"?jsonRow("project_items","pi","id project_id project_content_id deleted_at revision last_mutation_id","pi.project_content_id=x.project_content_id"):"NULL",
    uploadReceipts:jsonRows("r2_upload_requests","ur","id status purpose request_scope request_sha256 storage_profile_id storage_profile_revision candidate_object_key accepted_result_json completed_at expires_at",`ur.candidate_object_key=(${rk}) OR CASE WHEN json_valid(ur.accepted_result_json) THEN json_extract(ur.accepted_result_json,'$.key') END=(${rk})`),
    metrologyReceipts:jsonRows("metrology_reference_upload_requests","ur","id status purpose request_scope request_sha256 storage_profile_id storage_profile_revision candidate_object_key accepted_result_json completed_at expires_at",`ur.candidate_object_key=(${rk}) OR CASE WHEN json_valid(ur.accepted_result_json) THEN json_extract(ur.accepted_result_json,'$.reference.assetKey') END=(${rk})`),
    commentReceipts:jsonRows("comment_item_acceptances","ur","item_id submission_id status purpose expected_sha256 expected_byte_size storage_profile_id storage_profile_revision candidate_object_key accepted_result_json started_at",`(${s.table==="comment_submission_items"?"ur.item_id=x.id":"0"}) OR ur.candidate_object_key=${key} OR CASE WHEN json_valid(ur.accepted_result_json) THEN json_extract(ur.accepted_result_json,'$.objectKey') END=${key}`,"item_id"),
    submissionReceipt:jsonRow("comment_submission_acceptances","ca","submission_id status request_sha256 created_at completed_at expires_at",`ca.submission_id=${sub}`),
    gc:jsonRows("blob_gc_ledger","bg","store_kind provider object_key state operation_id deletion_started_at deleted_at attempt_count updated_at",`(bg.store_kind='r2' AND bg.provider='r2' AND bg.object_key=(${rk})) OR(bg.store_kind='managed' AND bg.provider=(${mp}) AND bg.object_key=(${mk}))`,"store_kind provider object_key"),
    quarantine:jsonRows("blob_integrity_quarantine","bq","store_kind provider object_key reason expected_byte_size observed_byte_size operation_id detected_at last_checked_at",`(bq.store_kind='r2' AND bq.provider='r2' AND bq.object_key=(${rk})) OR(bq.store_kind='managed' AND bq.provider=(${mp}) AND bq.object_key=(${mk}))`,"store_kind provider object_key"),
    mappings:jsonRows("legacy_file_mappings","lm","store_kind provider object_key file_id location_id classification observed_at",`(lm.store_kind='r2' AND lm.provider='r2' AND lm.object_key=(${rk})) OR(lm.store_kind='managed' AND lm.provider=(${mp}) AND lm.object_key=(${mk}))`,"store_kind provider object_key"),
    // Profiles are immutable and few; capturing the complete non-secret configuration
    // set conservatively invalidates pending shadow work on an explicit profile change.
    profiles:jsonRows("storage_profiles","sp","id adapter_type namespace_identity configuration_source configuration_revision state created_at","1=1"),
    profileRuntime:jsonRows("storage_profile_runtime","sp","storage_profile_id state registered_at activated_at retired_at","1=1","storage_profile_id"),
  };
  const hasSubmission=sub!=="NULL",hasStep=step!=="NULL",hasSample=hasStep||hasSubmission||s.table==="events"||s.table==="state_verifications";
  if(!hasSample)delete parts.sample;
  if(!hasStep){delete parts.run;delete parts.step;}
  if(!hasSubmission)for(const name of ["submission","submissionTargets","targetSteps","targetRuns","targetSamples","submissionReceipt"])delete parts[name];
  if(s.table!=="comment_submission_items")delete parts.pairedItem;
  if(s.table!=="state_representation_assets")delete parts.state;
  if(s.table!=="metrology_template_references")delete parts.template;
  if(s.table!=="project_content_attachments")for(const name of ["projectContent","project","projectItem"])delete parts[name];
  if(!s.managed)delete parts.sourceManaged;
  delete parts.profiles;delete parts.profileRuntime;
  parts.profileRevision="(SELECT count(*) FROM file_shadow_dependency_versions WHERE dependency_kind IN('storage_profiles','storage_profile_runtime'))";
  return `json_object(${Object.entries(parts).map(([name,value])=>`${q(name)},json(${value})`).join(",")})`;
}
function sourceSelect(s) {
  const rk=s.direct??(s.asset?"a.r2_key":"NULL");
  const mk=s.managed?"m.object_key":"NULL",mp=s.managed?"m.provider":"NULL";
  const joined=`FROM ${s.table} x ${s.asset?`LEFT JOIN assets a ON a.id=x.${s.asset}`:""} ${s.managed?`LEFT JOIN managed_storage_objects m ON m.id=x.${s.managed}`:""}`;
  const store=`CASE WHEN (${rk}) IS NOT NULL AND (${mk}) IS NULL THEN 'r2' WHEN (${rk}) IS NULL AND (${mk}) IS NOT NULL THEN 'managed' END`;
  return `SELECT ${q(s.kind)} consumer_kind,x.${s.id??"id"} consumer_id,${s.sub?`x.${s.sub}`:"''"} consumer_sub_id,${q(s.slot)} file_slot,x.rowid source_rowid,
    json_object(${cols("x",s.columns)}${s.extra??""},'resolved_r2_key',${jsonScalar(rk)},'resolved_managed_provider',${jsonScalar(mp)},'resolved_managed_key',${jsonScalar(mk)},'expected_purpose',${s.purpose},'_dependencies',json(${dependencyJson(s,rk,mk,mp)})) source_json,
    ${store} legacy_store_kind,CASE ${store} WHEN 'r2' THEN 'r2' WHEN 'managed' THEN ${mp} END legacy_provider,CASE ${store} WHEN 'r2' THEN ${rk} WHEN 'managed' THEN ${mk} END legacy_object_key,${s.purpose} expected_purpose ${joined} ${s.where?`WHERE (${s.where})`:""}`;
}
// Keep every D1 statement below 100 KB; a compound view must not inline all
// thirteen complete dependency projections in its CREATE statement.
const sourceViewName=(s)=>`file_shadow_sources_${s.kind}_${s.slot}`;
for (const s of slots) add(`CREATE VIEW ${sourceViewName(s)} AS ${sourceSelect(s)};`);
// D1 also caps the terms in one compound SELECT; each level stays at five.
for (const [n,part] of [["relational",slots.slice(0,5)],["content",slots.slice(5,8)],["direct",slots.slice(8)]]) add(`CREATE VIEW file_shadow_sources_${n} AS ${part.map((s)=>`SELECT * FROM ${sourceViewName(s)}`).join(" UNION ALL ")};`);
add("CREATE VIEW file_shadow_sources AS SELECT * FROM file_shadow_sources_relational UNION ALL SELECT * FROM file_shadow_sources_content UNION ALL SELECT * FROM file_shadow_sources_direct;");
const sourceKeySelect=(s)=>`SELECT ${q(s.kind)} consumer_kind,x.${s.id??"id"} consumer_id,${s.sub?`x.${s.sub}`:"''"} consumer_sub_id,${q(s.slot)} file_slot,x.rowid source_rowid FROM ${s.table} x ${s.where?`WHERE (${s.where})`:""}`;
for (const [n,part] of [["relational",slots.slice(0,5)],["content",slots.slice(5,8)],["direct",slots.slice(8)]]) add(`CREATE VIEW file_shadow_source_keys_${n} AS ${part.map(sourceKeySelect).join(" UNION ALL ")};`);
add("CREATE VIEW file_shadow_source_keys AS SELECT * FROM file_shadow_source_keys_relational UNION ALL SELECT * FROM file_shadow_source_keys_content UNION ALL SELECT * FROM file_shadow_source_keys_direct;");
const namespaceEvidence = `SELECT m.store_kind,m.provider,m.object_key,l.storage_profile_id,p.configuration_revision FROM legacy_file_mappings m JOIN file_locations l ON l.id=m.location_id JOIN storage_profiles p ON p.id=l.storage_profile_id
UNION SELECT 'r2','r2',r.candidate_object_key,r.storage_profile_id,r.storage_profile_revision FROM r2_upload_requests r
UNION SELECT 'r2','r2',CASE WHEN json_valid(r.accepted_result_json) THEN json_extract(r.accepted_result_json,'$.key') END,r.storage_profile_id,r.storage_profile_revision FROM r2_upload_requests r WHERE r.status='ready'
UNION SELECT 'r2','r2',r.candidate_object_key,r.storage_profile_id,r.storage_profile_revision FROM metrology_reference_upload_requests r
UNION SELECT 'r2','r2',CASE WHEN json_valid(r.accepted_result_json) THEN json_extract(r.accepted_result_json,'$.reference.assetKey') END,r.storage_profile_id,r.storage_profile_revision FROM metrology_reference_upload_requests r WHERE r.status='ready'
UNION SELECT CASE WHEN r.purpose='research_source' THEN 'managed' ELSE 'r2' END,CASE WHEN r.purpose='research_source' THEN 'switchdrive' ELSE 'r2' END,r.candidate_object_key,r.storage_profile_id,r.storage_profile_revision FROM comment_item_acceptances r
UNION SELECT CASE WHEN json_valid(r.accepted_result_json) THEN json_extract(r.accepted_result_json,'$.storeKind') END,CASE WHEN json_valid(r.accepted_result_json) THEN json_extract(r.accepted_result_json,'$.provider') END,CASE WHEN json_valid(r.accepted_result_json) THEN json_extract(r.accepted_result_json,'$.objectKey') END,r.storage_profile_id,r.storage_profile_revision FROM comment_item_acceptances r WHERE r.status='ready'
UNION SELECT 'r2','r2',i.workbook_asset_key,i.storage_profile_id,i.storage_profile_revision FROM imports i WHERE i.client_request_id IS NOT NULL
UNION SELECT 'r2','r2',i.manifest_asset_key,i.storage_profile_id,i.storage_profile_revision FROM imports i WHERE i.client_request_id IS NOT NULL
UNION SELECT 'r2','r2',a.r2_key,i.storage_profile_id,i.storage_profile_revision FROM assets a JOIN imports i ON i.id=a.import_id WHERE i.client_request_id IS NOT NULL`.split("\nUNION ");
for (const [name,terms] of [["mapping",namespaceEvidence.slice(0,1)],["uploads",namespaceEvidence.slice(1,5)],["comments",namespaceEvidence.slice(5,7)],["imports",namespaceEvidence.slice(7)]]) add(`CREATE VIEW file_shadow_namespace_${name} AS ${terms.join(" UNION ")};`);
add("CREATE VIEW file_shadow_namespace_evidence AS SELECT * FROM file_shadow_namespace_mapping UNION SELECT * FROM file_shadow_namespace_uploads UNION SELECT * FROM file_shadow_namespace_comments UNION SELECT * FROM file_shadow_namespace_imports;");
const dependencySnapshot=(table,alias)=>`json_object(${cols(alias,[...dependencySpecs.get(table)].join(" "))})`;
function captureDependencies(table) {
  if(!dependencySpecs.has(table))return "";
  const key=dependencyKey(table,"x"),snapshot=dependencySnapshot(table,"x");
  return `INSERT INTO file_shadow_dependency_versions(dependency_kind,dependency_key,revision,present,snapshot_json)
  SELECT ${q(table)},${key},COALESCE((SELECT MAX(v.revision) FROM file_shadow_dependency_versions v WHERE v.dependency_kind=${q(table)} AND v.dependency_key=${key}),0)+1,1,${snapshot}
  FROM ${table} x WHERE NOT EXISTS(SELECT 1 FROM file_shadow_dependency_versions v WHERE v.dependency_kind=${q(table)} AND v.dependency_key=${key} AND v.revision=(SELECT MAX(w.revision) FROM file_shadow_dependency_versions w WHERE w.dependency_kind=v.dependency_kind AND w.dependency_key=v.dependency_key) AND v.present=1 AND v.snapshot_json IS ${snapshot});
  INSERT INTO file_shadow_dependency_versions(dependency_kind,dependency_key,revision,present,snapshot_json)
  SELECT v.dependency_kind,v.dependency_key,v.revision+1,0,'null' FROM file_shadow_dependency_versions v
  WHERE v.dependency_kind=${q(table)} AND v.present=1 AND v.revision=(SELECT MAX(w.revision) FROM file_shadow_dependency_versions w WHERE w.dependency_kind=v.dependency_kind AND w.dependency_key=v.dependency_key)
  AND NOT EXISTS(SELECT 1 FROM ${table} x WHERE ${key}=v.dependency_key);`;
}
for(const table of dependencySpecs.keys()) {
 add(`CREATE INDEX file_shadow_dependency_${table}_key_idx ON ${table}(${dependencyKey(table,"")});`);
 add(captureDependencies(table));
}
// Triggers reconcile actual rows, not NEW's possibly pre-normalization values.
// Missing-owner sweep catches SQLite REPLACE implicit deletes even with recursive_triggers=OFF.
function sync(filter="1=1",force="0") {
  const changed=`h.occurrence_id IS NULL OR h.present<>1 OR h.source_rowid IS NOT s.source_rowid OR h.source_json IS NOT s.source_json OR (${force})`;
  return `INSERT INTO file_shadow_occurrences(id,${keys.join(",")},generation,present,source_rowid,source_json,legacy_store_kind,legacy_provider,legacy_object_key,expected_purpose,observed_epoch,observed_at)
    SELECT 'shadow:'||lower(hex(randomblob(16))),${keys.map((k)=>`s.${k}`).join(",")},COALESCE(h.generation,0)+1,1,s.source_rowid,s.source_json,s.legacy_store_kind,s.legacy_provider,s.legacy_object_key,s.expected_purpose,${epoch},${stamp}
    FROM (WITH current_sources AS MATERIALIZED (SELECT * FROM file_shadow_sources) SELECT * FROM current_sources) s LEFT JOIN file_shadow_heads h ON ${same("h","s")} WHERE (${filter.replaceAll("K.","s.")}) AND (${changed});
    INSERT INTO file_shadow_occurrences(id,${keys.join(",")},generation,present,source_rowid,source_json,legacy_store_kind,legacy_provider,legacy_object_key,expected_purpose,observed_epoch,observed_at)
    SELECT 'shadow:'||lower(hex(randomblob(16))),${keys.map((k)=>`h.${k}`).join(",")},h.generation+1,0,NULL,'{}',NULL,NULL,NULL,NULL,${epoch},${stamp}
    FROM file_shadow_heads h WHERE h.present=1 AND (${filter.replaceAll("K.","h.")}) AND NOT EXISTS(SELECT 1 FROM file_shadow_source_keys s WHERE ${same("h","s")});
    INSERT INTO file_shadow_closures(occurrence_id,successor_occurrence_id,closed_epoch,closed_at)
    SELECT h.occurrence_id,o.id,o.observed_epoch,o.observed_at FROM file_shadow_occurrences o JOIN file_shadow_heads h ON ${same("h","o")} AND o.generation=h.generation+1
    WHERE o.observed_epoch=${epoch};
    INSERT INTO file_shadow_heads(${keys.join(",")},generation,occurrence_id,present,source_rowid,source_json,observed_epoch)
    SELECT ${keys.map((k)=>`o.${k}`).join(",")},o.generation,o.id,o.present,o.source_rowid,o.source_json,o.observed_epoch FROM file_shadow_occurrences o
    WHERE o.observed_epoch=${epoch} AND NOT EXISTS(SELECT 1 FROM file_shadow_closures c WHERE c.occurrence_id=o.id)
    ON CONFLICT(${keys.join(",")}) DO UPDATE SET generation=excluded.generation,occurrence_id=excluded.occurrence_id,present=excluded.present,source_rowid=excluded.source_rowid,source_json=excluded.source_json,observed_epoch=excluded.observed_epoch
    WHERE file_shadow_heads.generation<excluded.generation;`;
}
add(sync());
function reject(name,event,table,condition,message) {add(`CREATE TRIGGER ${name} BEFORE ${event} ON ${table} BEGIN SELECT RAISE(ABORT,${q(message)}) WHERE ${condition}; END;`);}
function immutable(table,pk) {
  reject(`${table}_replace_guard`,"INSERT",table,`EXISTS(SELECT 1 FROM ${table} o WHERE ${pk.map((k)=>`o.${k} IS NEW.${k}`).join(" AND ")})`,"Shadow immutable identity conflict");
  reject(`${table}_update_guard`,"UPDATE",table,"1","Shadow history is immutable");
  reject(`${table}_delete_guard`,"DELETE",table,"1","Shadow history cannot be deleted");
}
for (const [table,pk] of [["file_shadow_dependency_versions",["dependency_kind","dependency_key","revision"]],["file_shadow_legacy_deletion_claims",["store_kind","provider","object_key"]],["file_shadow_runtime_incarnations",["incarnation"]],["file_shadow_occurrences",["id"]],["file_shadow_closures",["occurrence_id"]],["file_shadow_enablements",["singleton"]],["file_shadow_decisions",["occurrence_id"]],["file_shadow_profile_enablements",["storage_profile_id"]],["file_shadow_reconciliations",["id"]],["file_shadow_checkpoints",["id"]]]) immutable(table,pk);
const dependencyExists=(includePayload)=>`CASE NEW.dependency_kind ${[...dependencySpecs.keys()].map((table)=>`WHEN ${q(table)} THEN EXISTS(SELECT 1 FROM ${table} x WHERE ${dependencyKey(table,"x")}=NEW.dependency_key${includePayload?` AND ${dependencySnapshot(table,"x")} IS NEW.snapshot_json`:""})`).join(" ")} ELSE 0 END`;
reject("file_shadow_dependency_versions_owner_guard","INSERT","file_shadow_dependency_versions",`NEW.revision<>COALESCE((SELECT MAX(v.revision)+1 FROM file_shadow_dependency_versions v WHERE v.dependency_kind=NEW.dependency_kind AND v.dependency_key=NEW.dependency_key),1) OR (NEW.present=1 AND NOT(${dependencyExists(true)})) OR (NEW.present=0 AND(NEW.snapshot_json<>'null' OR ${dependencyExists(false)} OR NOT EXISTS(SELECT 1 FROM file_shadow_dependency_versions v WHERE v.dependency_kind=NEW.dependency_kind AND v.dependency_key=NEW.dependency_key AND v.revision=NEW.revision-1 AND v.present=1)))`,"Dependency revision must record exact current metadata or disappearance");
reject("file_shadow_control_insert_guard","INSERT","file_shadow_control","1","Shadow control already exists");
reject("file_shadow_control_update_guard","UPDATE","file_shadow_control","NEW.singleton<>OLD.singleton OR NEW.epoch<>OLD.epoch+1","Shadow epoch must advance exactly once");
reject("file_shadow_control_delete_guard","DELETE","file_shadow_control","1","Shadow control cannot be deleted");
reject("file_shadow_runtime_insert_guard","INSERT","file_shadow_runtime_guard","1","Shadow runtime guard already exists");
reject("file_shadow_runtime_delete_guard","DELETE","file_shadow_runtime_guard","1","Shadow runtime guard cannot be deleted");
reject("file_shadow_runtime_update_guard","UPDATE","file_shadow_runtime_guard","NEW.singleton<>OLD.singleton OR (NEW.enabled=1 AND (NEW.incarnation IS OLD.incarnation OR EXISTS(SELECT 1 FROM file_shadow_runtime_incarnations h WHERE h.incarnation=NEW.incarnation) OR EXISTS(SELECT 1 FROM file_shadow_attempts a WHERE a.runtime_incarnation=NEW.incarnation) OR NOT EXISTS(SELECT 1 FROM file_authority_control WHERE singleton=1 AND mode='overlap'))) OR (NEW.enabled=0 AND NEW.incarnation IS NOT OLD.incarnation)","Shadow execution requires a fresh explicitly enabled incarnation");
reject("file_shadow_runtime_incarnations_admission_guard","INSERT","file_shadow_runtime_incarnations","NOT EXISTS(SELECT 1 FROM file_shadow_runtime_guard g WHERE g.singleton=1 AND g.enabled=1 AND g.incarnation=NEW.incarnation AND g.enabled_by=NEW.enabled_by AND g.updated_at=NEW.enabled_at)","Runtime incarnation history must match explicit local enablement");
add("CREATE TRIGGER file_shadow_runtime_remember AFTER UPDATE ON file_shadow_runtime_guard WHEN NEW.enabled=1 BEGIN INSERT INTO file_shadow_runtime_incarnations(incarnation,enabled_by,enabled_at) VALUES(NEW.incarnation,NEW.enabled_by,NEW.updated_at); END;");
reject("file_shadow_enablements_admission_guard","INSERT","file_shadow_enablements",`NEW.expected_epoch<>${epoch} OR NOT EXISTS(SELECT 1 FROM file_authority_control WHERE singleton=1 AND mode='legacy')`,"Shadow enablement baseline changed");
