add("CREATE TRIGGER file_shadow_enablements_apply AFTER INSERT ON file_shadow_enablements BEGIN UPDATE file_authority_control SET mode='overlap',updated_at=NEW.enabled_at,activated_at=NEW.enabled_at WHERE singleton=1; END;");
