reject("storage_profile_runtime_legacy_update_guard","UPDATE","storage_profile_runtime",`NOT(${enabled}) OR OLD.state<>'read_only' OR NEW.state<>'read_write' OR NEW.storage_profile_id IS NOT OLD.storage_profile_id OR NEW.registered_at IS NOT OLD.registered_at OR NEW.retired_at IS NOT NULL OR NOT EXISTS(SELECT 1 FROM file_shadow_profile_enablements e WHERE e.storage_profile_id=NEW.storage_profile_id AND NEW.activated_at IS e.enabled_at)`,"Profile write readiness requires explicit shadow admission");
